import json, os, glob

# Dump active factor metadata from factors/*.json (exclude .bak and factor_ensemble.json)
files = sorted(glob.glob('factors/*.json'))
for f in files:
    if f.endswith('.bak') or 'factor_ensemble' in f:
        continue
    try:
        d = json.load(open(f))
        meta = d.get('metadata', d)
        # print key fields
        keys_of_interest = ['factor_id','id','name','category','direction','ic','icir','q','quality','status','universe','description','notes']
        out = {}
        for k in keys_of_interest:
            if k in meta:
                out[k] = meta[k]
        print(f, '=>', json.dumps(out)[:600])
        print('---')
    except Exception as e:
        print(f, 'ERR', e)
EOF

