python - <<'EOF'
import json, os, glob

files = sorted(glob.glob('factors/*.json'))
for f in files:
    if f.endswith('.bak') or 'ensemble' in f:
        continue
    try:
        d = json.load(open(f))
        keys = list(d.keys())
        print('='*60)
        print(f, '| keys:', keys[:12])
        # print metadata fields compactly
        for k in keys:
            v = d[k]
            if isinstance(v, (int, float, str, bool)) or v is None:
                print(f'   {k}: {v}')
            elif isinstance(v, list) and len(v) < 20:
                print(f'   {k}: {v}')
            elif isinstance(v, dict):
                print(f'   {k}: dict keys={list(v.keys())[:8]}')
            else:
                print(f'   {k}: {type(v).__name__} len={len(v)}')
    except Exception as e:
        print(f, 'ERR', e)
EOF

