import csv, math, statistics, itertools

VIS = '2028-05-08'
assets = ['000300.SH','000688.SH','BTC','CN10Y','COPPER','ETH','HSI','N225','NDX','SOX','SPX','SX5E','US10Y','WTI','XAU']

def load_px(a):
    rows=list(csv.reader(open('../persistent/stock_data/%s.csv'%a)))
    hdr=rows[0]; ci=hdr.index('close')
    out=[]
    for r in rows[1:]:
        if not r or not r[0] or r[0]>VIS: continue
        try: out.append((r[0], float(r[ci])))
        except: pass
    return out

px={a:load_px(a) for a in assets}
# build date index from SPX
dates=[d for d,_ in px['SPX']]
P={a:{d:v for d,v in px[a]} for a in assets}

# helper: value of asset a at index i (date), with frozen-feed fallback (last known)
def val(a, date):
    s=P[a]
    # find last date <= given date
    while date not in s and date>dates[0]:
        # step back one calendar day
        from datetime import datetime, timedelta
        date=(datetime.strptime(date,'%Y-%m-%d')-timedelta(days=1)).strftime('%Y-%m-%d')
    return s.get(date)

import numpy as np
from datetime import datetime, timedelta

def prev_date(d, k=1):
    dt=datetime.strptime(d,'%Y-%m-%d')
    return (dt-timedelta(days=k)).strftime('%Y-%m-%d')

def ret_over(a, d0, d1):  # return from d0 to d1
    v0=val(a,d0); v1=val(a,d1)
    if v0 is None or v1 is None or v0==0: return 0.0
    return v1/v0-1.0

def day_index(d):
    return dates.index(d) if d in dates else None

# Build daily return matrix aligned to dates
rets={a:[] for a in assets}
for i in range(1,len(dates)):
    d=dates[i]; dp=dates[i-1]
    for a in assets:
        r=ret_over(a, dp, d)
        rets[a].append(r)

# --- compute factor time series at each date index i (>=60) ---
def factor_values(i):
    """returns dict asset->factor value as of dates[i]"""
    d=dates[i]
    out={}
    for a in assets:
        out[a]=None
    # rel_mom_20d_skip5: mom from t-20 to t-5
    d_t5 = dates[max(0,i-5)]; d_t20 = dates[max(0,i-20)]
    mom={a: ret_over(a, d_t20, d_t5) for a in assets}
    med=statistics.median(mom.values())
    for a in assets: out[a]=mom[a]-med
    # max_ret_20d: max daily ret over last 20
    for a in assets:
        seg=rets[a][max(0,i-20):i]
        out[a]=out.get(a,0) + 0  # placeholder, store separately
    return out

# Proper per-factor computation
F={}
def compute(name, i):
    d=dates[i]
    vals={}
    if name=='rel_mom_20d_skip5':
        d_t5=dates[max(0,i-5)]; d_t20=dates[max(0,i-20)]
        mom={a: ret_over(a,d_t20,d_t5) for a in assets}
        med=statistics.median(mom.values())
        return {a: mom[a]-med for a in assets}
    if name=='max_ret_20d':
        for a in assets:
            seg=rets[a][max(0,i-20):i]
            vals[a]=max(seg) if seg else 0.0
        return vals
    if name=='downside_vol_ratio_20':
        for a in assets:
            seg=rets[a][max(0,i-20):i]
            if len(seg)<10: vals[a]=0.0; continue
            neg=[r for r in seg if r<0]
            ds=math.sqrt(sum(r*r for r in neg)/len(seg)) if neg else 0.0
            tot=statistics.pstdev(seg)
            vals[a]= -(ds/tot) if tot>0 else 0.0
        return vals
    if name=='kurt_20d_skip5':
        for a in assets:
            seg=rets[a][max(0,i-25):i-5] if i>=25 else rets[a][max(0,i-20):i]
            if len(seg)<10: vals[a]=0.0; continue
            m=statistics.mean(seg); s=statistics.pstdev(seg)
            if s==0: vals[a]=0.0; continue
            n=len(seg)
            kurt=sum((x-m)**4 for x in seg)/n/(s**4)
            vals[a]=kurt
        return vals
    if name=='beta_ew_60d':
        mkt=[sum(rets[a][j] for a in assets)/len(assets) for j in range(max(0,i-60),i)]
        for a in assets:
            seg=rets[a][max(0,i-60):i]
            n=min(len(seg),len(mkt)); seg=seg[-n:]; mm=mkt[-n:]
            if n<30: vals[a]=0.0; continue
            ma=statistics.mean(seg); mb=statistics.mean(mm)
            cov=sum((x-ma)*(y-mb) for x,y in zip(seg,mm))/(n-1)
            vb=statistics.pstdev(mm)**2
            vals[a]= cov/vb if vb>0 else 0.0
        return vals
    if name=='corr_ew_60':
        for a in assets:
            cs=[]
            for b in assets:
                if b==a: continue
                seg=rets[a][max(0,i-60):i]; segb=rets[b][max(0,i-60):i]
                n=min(len(seg),len(segb)); seg=seg[-n:]; segb=segb[-n:]
                if n<30: continue
                ma=statistics.mean(seg); mb=statistics.mean(segb)
                sa=statistics.pstdev(seg); sb=statistics.pstdev(segb)
                if sa>0 and sb>0:
                    cs.append(sum((x-ma)*(y-mb) for x,y in zip(seg,segb))/(n-1)/(sa*sb))
            vals[a]= sum(cs)/len(cs) if cs else 0.0
        return vals
    if name=='dxy_beta_cond_60x20':
        dxy_rows=list(csv.reader(open('../persistent/index_data/DXY.csv')))
        ci=dxy_rows[0].index('close')
        dxy={r[0]:float(r[ci]) for r in dxy_rows[1:] if r and r[0] and r[0]<=VIS}
        dxy_dates=sorted(dxy.keys())
        def dxy_val(date):
            while date not in dxy and date>dxy_dates[0]:
                date=prev_date(date)
            return dxy.get(date)
        d0=dxy_val(d); d20=dxy_val(prev_date(d,20))
        cond=(d0/d20-1.0) if d0 and d20 else 0.0
        for a in assets:
            seg=rets[a][max(0,i-60):i]
            dseg=[]
            for j in range(max(0,i-60),i):
                dd=dates[j]
                dv=dxy_val(dd); dpv=dxy_val(prev_date(dd,1))
                dseg.append(dv/dpv-1.0 if dpv else 0.0)
            n=min(len(seg),len(dseg)); seg=seg[-n:]; dg=dseg[-n:]
            if n<30: vals[a]=0.0; continue
            ma=statistics.mean(seg); mb=statistics.mean(dg)
            cov=sum((x-ma)*(y-mb) for x,y in zip(seg,dg))/(n-1)
            vb=statistics.pstdev(dg)**2
            beta=cov/vb if vb>0 else 0.0
            vals[a]= -beta*cond
        return vals
    return vals

# forward 10d return
def fwd10(i):
    d=dates[i]
    d10=dates[min(len(dates)-1,i+10)]
    return {a: ret_over(a,d,d10) for a in assets}

def rank_ic(vals, fwd):
    xs=[]; ys=[]
    for a in assets:
        if vals[a] is None: continue
        xs.append(vals[a]); ys.append(fwd[a])
    # spearman
    rx={v:i for i,v in enumerate(sorted(xs))}
    ry={v:i for i,v in enumerate(sorted(ys))}
    n=len(xs)
    if n<8: return float('nan')
    sx=[rx[x] for x in xs]; sy=[ry[y] for y in ys]
    mx=statistics.mean(sx); my=statistics.mean(sy)
    cov=sum((x-mx)*(y-my) for x,y in zip(sx,sy))/(n-1)
    sdx=statistics.pstdev(sx); sdy=statistics.pstdev(sy)
    return cov/(sdx*sdy) if sdx>0 and sdy>0 else 0.0

names=['rel_mom_20d_skip5','downside_vol_ratio_20','beta_ew_60d','corr_ew_60','kurt_20d_skip5','max_ret_20d','dxy_beta_cond_60x20']
for win_label, n_obs in [('last60',60),('last250',250)]:
    ics={}
    for name in names:
        vals_list=[]; fwd_list=[]
        for i in range(len(dates)-10-n_obs, len(dates)-10):
            v=compute(name,i); f=fwd10(i)
            vals_list.append(v); fwd_list.append(f)
        ics[name]=statistics.mean([rank_ic(v,f) for v,f in zip(vals_list,fwd_list)])
    print('=== h10 rank-IC mean, %s ==='%win_label)
    for name in names:
        print('  %-24s IC=%.4f'%(name, ics[name]))
EOF

