ASSETS=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def load(fp):
    rows=list(csv.reader(open(fp))); hdr=rows[0]; idx={c:i for i,c in enumerate(hdr)}; out=[]
    for r in rows[1:]:
        d=r[idx['date']]
        if d>VIS: continue
        try: c=float(r[idx['close']])
        except: continue
        out.append((d,c))
    out.sort(); return out
p={a:load(f'../persistent/stock_data/{a}.csv') for a in ASSETS}
live=[a for a in ASSETS if p[a][-1][1]!=p[a][-2][1] or a not in ('000688.SH','SOX','NDX','CN10Y')]
# find truly live (non-flat last 60d)
live=[a for a in ASSETS if abs(p[a][-1][1]-p[a][-61][1])>1e-9]
print('live names:', live)
common=set(p['SPX'][i][0] for i in range(len(p['SPX'])))
for a in live: common&=set(x[0] for x in p[a])
common=sorted(common)
print('common dates:', len(common))
import numpy as np
def rbd(a):
    d={x[0]:x[1] for x in p[a]}; out=[]
    for i in range(1,len(common)):
        d0,d1=common[i-1],common[i]
        out.append(math.log(d[d1]/d[d0]) if d0 in d and d1 in d and d[d0]>0 else 0.0)
    return out
R=np.array([rbd(a) for a in live])
for n in (10,20,60):
    C=np.corrcoef(R[:,-n:]); m=~np.eye(C.shape[0],dtype=bool)
    print(f'live mean pairwise corr last {n}d: {C[m].mean():.3f}')
# dispersion: cross-sectional std of 20d returns
cs=[]
for i in range(len(common)-1):
    day=[]
    for a in live:
        d={x[0]:x[1] for x in p[a]}
        if common[i] in d and common[i+1] in d and d[common[i]]>0: day.append(math.log(d[common[i+1]]/d[common[i]]))
    if len(day)>=8: cs.append(np.std(day))
print('mean daily cross-sectional dispersion (live):', np.mean(cs[-20:])*100, '%')
