import pandas as pd, numpy as np
from scipy.stats import spearmanr

assets = ['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
data = {}
for a in assets:
    df = pd.read_csv(f'../persistent/stock_data/{a}.csv')
    df['date'] = pd.to_datetime(df['date'])
    df = df.sort_values('date').set_index('date')
    data[a] = df['close']
px = pd.DataFrame(data)
px = px[px.index <= pd.Timestamp('2029-05-07')]
ret = px.pct_change()
ew = ret.mean(axis=1)

def beta_ew(win=60):
    b = {}
    for a in assets:
        x = ret[a]; y = ew
        cov = x.rolling(win).cov(y); var = y.rolling(win).var()
        b[a] = cov/var
    return pd.DataFrame(b)

def corr_ew(win=60):
    out = {}
    for a in assets:
        cs = []
        for b in assets:
            if b != a:
                cs.append(ret[a].rolling(win).corr(ret[b]))
        out[a] = pd.concat(cs, axis=1).mean(axis=1)
    return pd.DataFrame(out)

def downside_vol_ratio(win=20):
    out = {}
    for a in assets:
        r = ret[a]
        downside = r.where(r < 0, 0.0)
        ds = downside.rolling(win).std()
        tot = r.rolling(win).std()
        out[a] = -(ds/tot)
    return pd.DataFrame(out)

def dxy_cond(win=60, cwin=20):
    dxy = pd.read_csv('../persistent/index_data/DXY.csv'); dxy['date']=pd.to_datetime(dxy['date']); dxy=dxy.set_index('date')['close'].sort_index()
    dxy = dxy[dxy.index <= pd.Timestamp('2029-05-07')]
    dxyr = dxy.pct_change()
    dxy_move = dxy/dxy.shift(cwin) - 1
    out = {}
    for a in assets:
        cov = ret[a].rolling(win).cov(dxyr); var = dxyr.rolling(win).var()
        b = cov/var
        out[a] = -b * dxy_move
    return pd.DataFrame(out)

def eurusd_cond(win=60, cwin=20):
    eur = pd.read_csv('../persistent/index_data/EURUSD.csv'); eur['date']=pd.to_datetime(eur['date']); eur=eur.set_index('date')['close'].sort_index()
    eur = eur[eur.index <= pd.Timestamp('2029-05-07')]
    eurr = eur.pct_change()
    eur_move = eur/eur.shift(cwin) - 1
    out = {}
    for a in assets:
        cov = ret[a].rolling(win).cov(eurr); var = eurr.rolling(win).var()
        b = cov/var
        out[a] = b * eur_move
    return pd.DataFrame(out)

def kurt_20_skip5(win=20):
    out = {}
    for a in assets:
        r = ret[a]
        k = r.shift(6).rolling(win).kurt()  # skip 5 days
        out[a] = k
    return pd.DataFrame(out)

def max_ret_20(win=20):
    return ret.rolling(win).max()

def rel_mom_20_skip5(win=20):
    mom = (px/px.shift(win+5) - 1)
    out = mom.sub(mom.median(axis=1), axis=0)
    return out

factors = {
 'beta_ew_60d': (beta_ew(), 1),
 'corr_ew_60': (corr_ew(), 1),
 'downside_vol_ratio_20': (downside_vol_ratio(), 1),
 'dxy_beta_cond_60x20': (dxy_cond(), -1),
 'eurusd_beta_cond_60x20': (eurusd_cond(), 1),
 'kurt_20d_skip5': (kurt_20_skip5(), 1),
 'max_ret_20d': (max_ret_20(), 1),
 'rel_mom_20d_skip5': (rel_mom_20_skip5(), 1),
}

# forward 10d returns
fwd = px.shift(-10)/px - 1
fwd = fwd.shift(1)  # factor at t predicts return t..t+10? use close[t]/close[t-1]... use simple: fwd at t = px[t+10]/px[t]-1

# align: factor date t uses data up to t; forward return from t to t+10
for name,(sig,dirn) in factors.items():
    idx = sig.index
    # rank IC per date over last 180 trading days
    ics_180, ics_60 = [], []
    dates = idx[idx <= pd.Timestamp('2029-05-07')]
    dates180 = dates[-181:-10]
    dates60 = dates[-61:-10]
    for t in dates180:
        f = sig.loc[t]; r = fwd.loc[t]
        m = f.notna() & r.notna()
        if m.sum() >= 8:
            ic = spearmanr(f[m], r[m]).statistic
            ics_180.append(ic)
    for t in dates60:
        f = sig.loc[t]; r = fwd.loc[t]
        m = f.notna() & r.notna()
        if m.sum() >= 8:
            ic = spearmanr(f[m], r[m]).statistic
            ics_60.append(ic)
    ics_180 = np.array(ics_180); ics_60 = np.array(ics_60)
    adj_180 = dirn*ics_180; adj_60 = dirn*ics_60
    print(f'{name:24s} dir={dirn:+d} | 180d: meanIC={adj_180.mean():+.4f} icir={adj_180.mean()/adj_180.std():+.3f} n={len(adj_180)} hit={np.mean(adj_180>0):.2f} | 60d: meanIC={adj_60.mean():+.4f} icir={adj_60.mean()/adj_60.std():+.3f} n={len(adj_60)} hit={np.mean(adj_60>0):.2f}')
"

