    df = df.sort_values('date').set_index('date')
    data[a] = df['close']
px = pd.DataFrame(data)
px = px[px.index <= pd.Timestamp('2029-05-07')]
ret = px.pct_change()
ew = ret[active].mean(axis=1)

def beta_ew(win=60):
    b = {}
    for a in assets:
        x = ret[a]; y = ew
        b[a] = x.rolling(win).cov(y)/y.rolling(win).var()
    return pd.DataFrame(b)

def corr_ew(win=60):
    out = {}
    for a in assets:
        cs = [ret[a].rolling(win).corr(ret[b]) for b in assets if b != a]
        out[a] = pd.concat(cs, axis=1).mean(axis=1)
    return pd.DataFrame(out)

def downside_vol_ratio(win=20):
    out = {}
    for a in assets:
        r = ret[a]
        out[a] = -(r.where(r<0,0.0).rolling(win).std()/r.rolling(win).std())
    return pd.DataFrame(out)

def fx_cond(sym, win=60, cwin=20):
    fx = pd.read_csv(f'../persistent/index_data/{sym}.csv'); fx['date']=pd.to_datetime(fx['date']); fx=fx.set_index('date')['close'].sort_index()
    fx = fx[fx.index <= pd.Timestamp('2029-05-07')]
    fxr = fx.pct_change(); move = fx/fx.shift(cwin)-1
    out = {}
    for a in assets:
        b = ret[a].rolling(win).cov(fxr)/fxr.rolling(win).var()
        out[a] = b*move
    return pd.DataFrame(out)

def kurt_20_skip5(win=20):
    out = {}
    for a in assets:
        out[a] = ret[a].shift(6).rolling(win).kurt()
    return pd.DataFrame(out)

factors = {
 'beta_ew_60d': (beta_ew(), 1),
 'corr_ew_60': (corr_ew(), 1),
 'downside_vol_ratio_20': (downside_vol_ratio(), 1),
 'dxy_beta_cond_60x20': (fx_cond('DXY'), -1),
 'eurusd_beta_cond_60x20': (fx_cond('EURUSD'), 1),
 'kurt_20d_skip5': (kurt_20_skip5(), 1),
 'max_ret_20d': (ret.rolling(20).max(), 1),
 'rel_mom_20d_skip5': ((px/px.shift(25)-1).sub((px/px.shift(25)-1).median(axis=1),axis=0), 1),
}
fwd = (px.shift(-10)/px - 1)
for name,(sig,dirn) in factors.items():
