            m = f.notna() & r.notna()
            if m.sum() >= 6:
                ics.append(dirn*spearmanr(f[m], r[m]).statistic)
        ics = np.array(ics)
        print(f'  {label}: 60d meanIC={ics.mean():+.4f} icir={ics.mean()/ics.std():+.3f} hit={np.mean(ics>0):.2f} n={len(ics)}')
"

